		db.Node("start");
		db.Say("", "\"Doctor. I'd know that cough through a wall. Ward three's gone, you know. All of it. We're what's left of the rota.\"");
		db.Conv("opening.greet.drifter", "opening", "cflag:opening.step=1 & bg:drifter", "", 0, 5, "plain");
		db.Node("start");
