		db.Node("start");
		db.Say("", "\"It's you. You fixed my van twice and charged me once. I always meant to pay the other one.\"");
		db.Conv("opening.greet.nurse", "opening", "cflag:opening.step=1 & bg:nurse", "", 0, 5, "plain");
		db.Node("start");
		db.Say("", "\"Christ. It's you. You did my boy's stitches in May. He still shows people the scar, when there's people to show.\"");
		db.Conv("opening.greet.police", "opening", "cflag:opening.step=1 & bg:police", "", 0, 5, "plain");
		db.Node("start");
		db.Say("", "\"Officer. You bought one apple every morning and never ate it. I used to wonder about that. I still do.\"");
		db.Conv("opening.greet.radioham", "opening", "cflag:opening.step=1 & bg:radioham", "", 0, 5, "plain");
		db.Node("start");
		db.Say("", "\"I know that voice. Half past one, the night band. You always signed off with the weather.\"");
		db.Conv("opening.greet.raider", "opening", "cflag:opening.step=1 & bg:raider", "", 0, 5, "plain");
		db.Node("start");
		db.Say("", "\"You. You took my watch in March. Keep it. I want something else from you, and it isn't what you think.\"");
		db.Conv("opening.greet.soldier", "opening", "cflag:opening.step=1 & bg:soldier", "", 0, 5, "plain");
		db.Node("start");
		db.Say("", "\"Sarge? It's me. The line went and I never made it back to it. Looks like you didn't either.\"");
		db.Conv("opening.greet.unemployed", "opening", "cflag:opening.step=1 & bg:unemployed", "", 0, 5, "plain");
		db.Node("start");
		db.Say("", "\"You're alive. Good. Don't worry about the money. Money's a joke now, and not a good one.\"");
		db.Conv("opening.where_now", "opening", "cflag:opening.step=3", "Ask where they'll go now.", 4, 1, "plain");
		db.Node("start");
		db.Say("cflag:opening.end=3", "\"Not where you're going. They'd have the coat off my back before I'd said hello. I'll find a door.\"");
		db.Say("", "\"Behind you, at a distance. I'm slower than I look, and I look slow. Don't wait for me.\"");
