		db.Choice("fine", "\"Mind how you go.\"", "hub", "", "", "", "", "", "", "", "");
		db.Node("come");
		db.Say("", "\"I will. Just not at your pace. Go on. If I'm not there by dark, I found somewhere better.\"");
		db.Choice("back1", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
