		db.Node("start");
		db.Say("", "\"Fewer than you'd hope. More than you'd think. Most are behind doors, same as you were.\"");
		db.Say("", "\"The ones who went for the roads in the first week, I don't count them any more. It's easier.\"");
		db.Choice("road", "\"What happened on the roads?\"", "road", "", "", "", "", "", "", "", "");
		db.Choice("back", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
		db.Node("road");
		db.Say("", "\"Concrete where the bridges were. Drones over the fields. A loudspeaker that knows your name before you've said it.\"");
		db.Choice("back1", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
		db.Conv("opening.who_holds", "opening", "cflag:opening.step>=2 & cflag:opening.step<=3", "Ask who's in charge now.", 2, 1, "plain");
		db.Node("start");
		db.Say("", "\"Depends where you stand. The soldiers count you. The red-hand lot charge you. The lab people want your blood, politely.\"");
		db.Say("", "\"And the safehouses feed you if you work. That's the whole government now. Pick one before one picks you.\"");
		db.Choice("lab", "\"The lab people?\"", "lab", "", "", "", "", "", "", "", "");
